//! The Rust backend (spec chapter 8).
//!
//! It reads only the IR. Each module becomes a file of a Cargo project (spec chapter 8, section
//! 2), built as a Rust tree and then printed. std and the runtime are the module `wolf_rt`, which
//! holds only the pieces the program uses.

mod emit;
mod names;
mod rs;
mod runtime;

use wolf_ir::{Program, ProgramKind};

pub use emit::TestEntry;

/// A generated file, with its path relative to `out/rust/`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OutFile {
    /// The path, with `/` separators.
    pub path: String,
    /// The contents.
    pub contents: String,
}

/// A generated project.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Project {
    /// The files, sorted by path.
    pub files: Vec<OutFile>,
    /// The tests of a test build, in the order of the report (by file, then by declaration).
    pub tests: Vec<TestEntry>,
}

/// Generates the Rust project for a program; with `tests`, a test build that also contains the
/// tests. An error names a construct the backend does not support yet; the driver reports it as
/// an internal compiler error.
pub fn generate(program: &Program, wolf_version: &str, tests: bool) -> Result<Project, String> {
    let mut e = emit::Emitter::new(program, tests);
    let mut files: Vec<OutFile> = e
        .files()?
        .into_iter()
        .map(|(path, contents)| OutFile { path, contents })
        .collect();
    files.push(OutFile {
        path: "src/wolf_rt.rs".to_string(),
        contents: runtime::file(&e.rt, wolf_version),
    });
    files.push(OutFile {
        path: "Cargo.toml".to_string(),
        // A `[[test]]` whose file is missing would break `cargo build`.
        contents: cargo_toml(
            program,
            wolf_version,
            if tests { &e.extra_test_targets } else { &[] },
        ),
    });
    files.sort_by(|a, b| a.path.cmp(&b.path));
    let mut list = e.test_list.clone();
    list.sort_by(|a, b| {
        let file = |t: &TestEntry| t.name.split(".wolf: ").next().unwrap_or("").to_string();
        file(a).cmp(&file(b))
    });
    Ok(Project { files, tests: list })
}

/// `Cargo.toml`; `tests` are the test targets that Cargo does not find by itself (spec chapter
/// 8, section 2.1).
fn cargo_toml(program: &Program, version: &str, tests: &[(String, String)]) -> String {
    // `panic` is not a setting of the test profile.
    let profiles = "\n[profile.dev]\noverflow-checks = true\npanic = \"unwind\"\n\n[profile.release]\noverflow-checks = true\npanic = \"unwind\"\n\n[profile.test]\noverflow-checks = true\n";
    let bin = bin_name(program);
    let mut kind = match program.kind {
        ProgramKind::Cli if bin != program.name => {
            format!("\n[[bin]]\nname = \"{bin}\"\npath = \"src/main.rs\"\n")
        }
        _ => String::new(),
    };
    for (name, path) in tests {
        kind.push_str(&format!(
            "\n[[test]]\nname = \"{name}\"\npath = \"{path}\"\n"
        ));
    }
    // `[extern.rust.dependencies]`, copied verbatim.
    let dependencies: String = program
        .dependencies
        .get("rust")
        .into_iter()
        .flatten()
        .map(|(name, version)| format!("{name} = {version:?}\n"))
        .collect();
    format!(
        "# Generated by wolf {version}. Do not edit.\n\n[package]\nname = \"{}\"\nversion = \"{}\"\nedition = \"2024\"\nrust-version = \"1.85\"\npublish = false\n{kind}\n[dependencies]\n{dependencies}\n# The generated project is a workspace of its own.\n[workspace]\n{profiles}",
        program.name, program.version
    )
}

/// The name of the binary of a `cli` program: the package name, unless Cargo reserves it for a
/// directory of its build (`deps`, `examples`, `build`, `incremental`); then `<name>-bin`.
pub fn bin_name(program: &Program) -> String {
    if ["deps", "examples", "build", "incremental"].contains(&program.name.as_str()) {
        format!("{}-bin", program.name)
    } else {
        program.name.clone()
    }
}

/// The crate name of a program: the package name with `_` for `-`.
pub fn crate_name(program: &Program) -> String {
    program.name.replace('-', "_")
}

/// The prefix of a path to code of the project in `native/rust/` (spec chapter 7, section 8.2a).
pub(crate) const NATIVE: &str = "native:";

/// Whether the program calls code of `native/rust/`; the crate then declares `mod native`.
pub(crate) fn uses_native(program: &Program) -> bool {
    program.modules.iter().flat_map(|m| &m.items).any(|item| {
        let paths = match item {
            wolf_ir::Item::ExternFn(x) => &x.paths,
            wolf_ir::Item::ExternType(x) => &x.paths,
            _ => return false,
        };
        paths.get("rust").is_some_and(|p| p.starts_with(NATIVE))
    })
}

/// The `mod.rs` files that declare the modules of `native/rust/` (spec chapter 8, section 8a).
/// `files` are the paths of the files there, relative to `native/rust/` with `/` separators; the
/// result goes to `src/native/`. With `wolf`, the root also declares `wolf`, the generated
/// modules of the native modules. A directory gets one unless it has a `mod.rs` or a sibling
/// `<dir>.rs` of its own, which then declares its modules itself. Files whose names are not Rust
/// identifiers are copied but not declared.
pub fn native_modules(files: &[String], wolf: bool) -> Vec<OutFile> {
    use std::collections::{BTreeMap, BTreeSet};
    let has = |f: &str| files.iter().any(|x| x == f);
    let mut kids: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    // `wolf`: the generated modules of the native modules (spec chapter 6, section 1a).
    let root = kids.entry(String::new()).or_default();
    if wolf {
        root.insert("wolf".to_string());
    }
    for file in files.iter().filter(|f| f.ends_with(".rs")) {
        let parts: Vec<&str> = file.split('/').collect();
        let Some((name, dirs)) = parts.split_last() else {
            continue;
        };
        // Each directory on the way is a module of its parent.
        for i in 0..dirs.len() {
            let parent = dirs.get(..i).unwrap_or(&[]).join("/");
            if let Some(d) = dirs.get(i) {
                kids.entry(parent).or_default().insert((*d).to_string());
            }
        }
        let stem = name.trim_end_matches(".rs");
        if stem != "mod" {
            kids.entry(dirs.join("/"))
                .or_default()
                .insert(stem.to_string());
        }
    }
    let mut out = Vec::new();
    for (dir, names) in kids {
        if !dir.is_empty() && (has(&format!("{dir}/mod.rs")) || has(&format!("{dir}.rs"))) {
            continue;
        }
        let items = names
            .into_iter()
            .filter(|n| is_ident(n))
            .map(|n| rs::Item::Mod("pub ".to_string(), names::value(&n)))
            .collect();
        let path = if dir.is_empty() {
            "src/native/mod.rs".to_string()
        } else {
            format!("src/native/{dir}/mod.rs")
        };
        out.push(OutFile {
            path,
            contents: rs::print(&rs::File {
                header: "Generated by wolf: the modules of `native/rust/`. Do not edit."
                    .to_string(),
                docs: Vec::new(),
                // Native code may hold items that wolfpack code does not call.
                attrs: if dir.is_empty() {
                    vec!["#![allow(dead_code)]".to_string()]
                } else {
                    Vec::new()
                },
                items,
            }),
        });
    }
    out
}

/// Whether `name` can be a Rust module name as it is.
fn is_ident(name: &str) -> bool {
    let mut chars = name.chars();
    chars
        .next()
        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
        && !["self", "super", "crate", "_"].contains(&name)
}

#[cfg(test)]
mod native_tests {
    use super::*;

    #[test]
    fn native_modules_declare_files_and_directories() {
        let files: Vec<String> = [
            "slug.rs",
            "text/case.rs",
            "text/deep/x.rs",
            "own/mod.rs",
            "own/a.rs",
            "my-file.rs",
            "notes.txt",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let out = native_modules(&files, false);
        let paths: Vec<&str> = out.iter().map(|f| f.path.as_str()).collect();
        assert_eq!(
            paths,
            [
                "src/native/mod.rs",
                "src/native/text/mod.rs",
                "src/native/text/deep/mod.rs"
            ]
        );
        let root = &out.first().map(|f| f.contents.clone()).unwrap_or_default();
        assert!(
            root.contains("pub mod own;\npub mod slug;\npub mod text;\n"),
            "{root}"
        );
        assert!(!root.contains("my-file"));
    }
}
